router_body:
name: plan
runs-on: ubuntu-24.04
timeout-minutes: 5
outputs:
  matrix_gate: ${{ steps.plan.outputs.matrix_gate }}
  macos_run: ${{ steps.plan.outputs.macos_run }}
  covered: ${{ steps.plan.outputs.covered }}
steps:
  - name: full job set selected
    if: ${{ github.event_name != 'pull_request' || contains(github.event.pull_request.labels.*.name, 'full-matrix') || contains(github.event.pull_request.labels.*.name, 'ci') || contains(github.event.pull_request.labels.*.name, 'release-matrix') }}
    run: echo 'SELECTED gate determinism'
  - uses: actions/checkout@v4
    id: checkout
    if: ${{ github.event_name != 'pull_request' || contains(github.event.pull_request.labels.*.name, 'full-matrix') || contains(github.event.pull_request.labels.*.name, 'ci') || contains(github.event.pull_request.labels.*.name, 'release-matrix') }}
  - name: local gate wiring proof
    if: ${{ github.event_name != 'pull_request' || contains(github.event.pull_request.labels.*.name, 'full-matrix') || contains(github.event.pull_request.labels.*.name, 'ci') || contains(github.event.pull_request.labels.*.name, 'release-matrix') }}
    run: python3 -I ci/local-gate-test.py
  - name: the planner can say no (ci/plan-test.py)
    if: ${{ steps.checkout.outcome == 'success' }}
    run: python3 -I ci/plan-test.py
  - name: the tree this run tests
    id: tree
    if: ${{ steps.checkout.outcome == 'success' }}
    run: echo "tree=$(git rev-parse 'HEAD^{tree}')" >> "$GITHUB_OUTPUT"
  - name: the tree under test is ${{ steps.tree.outputs.tree }}
    if: ${{ steps.checkout.outcome == 'success' }}
    run: test "$(git rev-parse 'HEAD^{tree}')" = "${{ steps.tree.outputs.tree }}"
  - id: plan
    if: ${{ steps.checkout.outcome == 'success' }}
    env:
      PLAN_TOKEN: ${{ github.token }}
    run: python3 -I ci/plan.py --github-output "$GITHUB_OUTPUT"
  - name: the macOS payload of the run this push relies on
    if: ${{ steps.plan.outputs.macos_run != '' }}
    uses: actions/upload-artifact@v4
    with:
      name: canonical-arm64
      path: canonical-arm64/canonical.payload.tar
      if-no-files-found: error
  - name: local evidence gate
    if: ${{ !(github.event_name != 'pull_request' || contains(github.event.pull_request.labels.*.name, 'full-matrix') || contains(github.event.pull_request.labels.*.name, 'ci') || contains(github.event.pull_request.labels.*.name, 'release-matrix')) }}
    run: echo 'Local gauntlet evidence is the gate; request ci or full-matrix for CI.'
